def safe_divide(a, b):
    if b == 0: return None
    return round(a / b, 2)

def normalize_score(scores):
    if not scores: return []
    lo, hi = min(scores), max(scores)
    if lo == hi: return [0.0] * len(scores)
    return [round((x-lo)/(hi-lo), 3) for x in scores]

